import{b as t,O as a,g as e,j as i}from"./chunks/framework.DcaUmd3X.js";const c=JSON.parse('{"title":"命令行模式与 HTML 报告","description":"","frontmatter":{},"headers":[],"relativePath":"performance/jmeter/cli-report/index.md","filePath":"性能测试/1.Jmeter/07.命令行模式与HTML报告.md","lastUpdated":1781755252000}'),n={name:"performance/jmeter/cli-report/index.md"};function r(l,s,p,h,d,o){return a(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="命令行模式与-html-报告" tabindex="-1">命令行模式与 HTML 报告 <a class="header-anchor" href="#命令行模式与-html-报告" aria-label="Permalink to &quot;命令行模式与 HTML 报告&quot;">​</a></h1><blockquote><p>GUI 是给你调试脚本的，正式压测必须用命令行。否则 JMeter 自己的界面渲染就在跟你抢资源，测出来的数据不准。</p></blockquote><h2 id="cli-基本命令" tabindex="-1">CLI 基本命令 <a class="header-anchor" href="#cli-基本命令" aria-label="Permalink to &quot;CLI 基本命令&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 完整流程：跑压测 + 生成 HTML 报告</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jmeter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.jmx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> result.jtl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./report/</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 参数说明：</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -n  非 GUI 模式（Non-GUI）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -t  测试计划文件（Test plan）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -l  结果文件（Log）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -e  生成 HTML 报告（Export report）</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># -o  报告输出目录（Output）</span></span></code></pre></div><blockquote><p><code>-o</code> 指定的目录必须<strong>不存在或为空</strong>。如果已存在会报错，加 <code>-f</code> 强制覆盖。</p></blockquote><h2 id="从已有结果生成报告" tabindex="-1">从已有结果生成报告 <a class="header-anchor" href="#从已有结果生成报告" aria-label="Permalink to &quot;从已有结果生成报告&quot;">​</a></h2><p>如果之前只跑了 <code>-n -t -l</code> 没有加 <code>-e</code>，可以用 <code>-g</code> 从 JTL 文件单独生成报告：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jmeter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> result.jtl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./report/</span></span></code></pre></div><h2 id="jvm-调优" tabindex="-1">JVM 调优 <a class="header-anchor" href="#jvm-调优" aria-label="Permalink to &quot;JVM 调优&quot;">​</a></h2><p>压测机本身需要足够内存，尤其是模拟大量线程时：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 设置堆内存后启动 JMeter</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HEAP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-Xms2g -Xmx2g&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jmeter</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test.jmx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -l</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> result.jtl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./report/</span></span></code></pre></div><table tabindex="0"><thead><tr><th style="text-align:center;">并发规模</th><th>建议堆内存</th></tr></thead><tbody><tr><td style="text-align:center;">&lt; 100</td><td>1g</td></tr><tr><td style="text-align:center;">100~500</td><td>2g~4g</td></tr><tr><td style="text-align:center;">500~1000</td><td>4g~8g</td></tr><tr><td style="text-align:center;">&gt; 1000</td><td>考虑分布式压测</td></tr></tbody></table><h2 id="html-报告看什么" tabindex="-1">HTML 报告看什么 <a class="header-anchor" href="#html-报告看什么" aria-label="Permalink to &quot;HTML 报告看什么&quot;">​</a></h2><p>打开 <code>report/index.html</code>，三个核心板块：</p><p><strong>Dashboard 首页</strong> — 一句话结论：</p><table tabindex="0"><thead><tr><th>卡片</th><th>含义</th></tr></thead><tbody><tr><td>APDEX</td><td>0~1 综合评分，≥ 0.94 优秀</td></tr><tr><td>Requests Summary</td><td>成功/失败饼图</td></tr><tr><td>Statistics</td><td>全部请求的 Avg / Min / Max / P90 / P95 / P99 / Error% / TPS</td></tr><tr><td>Errors</td><td>Top 5 错误类型分布</td></tr><tr><td>Top 5 Errors by Sampler</td><td>按请求类型看错误分布</td></tr></tbody></table><p><strong>Charts 页面</strong> — 随时间变化的趋势图：</p><table tabindex="0"><thead><tr><th>图表</th><th>看什么</th></tr></thead><tbody><tr><td>Response Time Over Time</td><td>响应时间是否随时间恶化</td></tr><tr><td>Active Threads Over Time</td><td>线程启动曲线</td></tr><tr><td>Hits Per Second</td><td>每秒请求数趋势</td></tr><tr><td>Response Time Percentiles</td><td>P90/P95/P99 随时间变化</td></tr><tr><td>Latency Over Time</td><td>网络延迟趋势</td></tr><tr><td>Connect Time Over Time</td><td>建连耗时趋势</td></tr></tbody></table><p><strong>Customs Graphs 页面</strong> — 自定义图表，按需配置。</p><h2 id="user-properties-调优" tabindex="-1">user.properties 调优 <a class="header-anchor" href="#user-properties-调优" aria-label="Permalink to &quot;user.properties 调优&quot;">​</a></h2><p>在 JMeter 安装目录的 <code>bin/user.properties</code> 中调整，让报告更贴合你的需求：</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 报告时间粒度（毫秒），默认 60 秒一个数据点</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">jmeter.reportgenerator.overall_granularity</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=60000</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># APDEX 阈值（毫秒）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">jmeter.reportgenerator.apdex_satisfied_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=500   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ≤ 500ms 满意</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">jmeter.reportgenerator.apdex_tolerated_threshold</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1500   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ≤ 1500ms 可容忍</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 结果文件格式用 CSV（比 XML 更小更快）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">jmeter.save.saveservice.output_format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=csv</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 只记录失败的断言信息，减少 JTL 体积</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">jmeter.save.saveservice.assertion_results_failure_message</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=true</span></span></code></pre></div><blockquote><p>不要改 <code>jmeter.properties</code> 和 <code>reportgenerator.properties</code>，只在 <code>user.properties</code> 里覆盖需要的项。</p></blockquote><h2 id="实时监控" tabindex="-1">实时监控 <a class="header-anchor" href="#实时监控" aria-label="Permalink to &quot;实时监控&quot;">​</a></h2><p>HTML 报告是跑完后看的。如果压测时间长，想实时看数据，加一个 Backend Listener 对接时序数据库：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JMeter → Backend Listener → InfluxDB → Grafana（实时大屏）</span></span></code></pre></div><p>右键 线程组 → 添加 → 监听器 → 后端监听器 (Backend Listener)，选择 <code>InfluxDB</code> 后端，配置数据库地址即可。Grafana 有现成的 JMeter 仪表盘模板，导入就能用。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><strong>正式压测用 CLI</strong>：<code>jmeter -n -t -l -e -o</code></li><li><strong>HTML 报告首页看 APDEX</strong>，趋势图看响应时间是否随时间恶化</li><li><strong>堆内存要给够</strong>：1000 并发以下单机 4g 通常够用</li><li><strong>结果文件用 CSV</strong>，不要用 XML</li><li><strong>实时监控</strong>用 Backend Listener + InfluxDB + Grafana</li></ul>`,29)])])}const g=t(n,[["render",r]]);export{c as __pageData,g as default};
